import{_ as n,a0 as a,w as r,s as l,ao as u,I as o,x as s,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB | LCTT x X-CMD","titleTemplate":false,"description":"只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB","title":"只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB","tag":"202111","desc":""},"relativePath":"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB.md","filePath":"[post].md"}'),m={name:"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB.md"};function d(c,t,f,w,h,B){const e=a("Link");return r(),l("div",null,[t[15]||(t[15]=u('<h1 id="只有-4mb-如何修复-etcher-和-rufus-创建-linux-usb-后-破坏-的-usb" tabindex="-1">只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB <a class="header-anchor" href="#只有-4mb-如何修复-etcher-和-rufus-创建-linux-usb-后-破坏-的-usb" aria-label="Permalink to “只有 4MB？如何修复 Etcher 和 Rufus 创建 Linux USB 后“破坏”的 USB”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202111/07/165254zlhgz6an6vgpv2qd.jpg" alt=""></p><p>情况是这样的。你用 Etcher 或者 Rufus 工具在 Windows 或者 Linux 中创建了一个可启动的、Live Linux USB。</p><p>你用它来安装 Linux，USB 的目的已经达到了。现在你想格式化这个 USB，用它来进行常规的数据传输或存储。</p><p>你把它插入你的 Windows 系统，令你吃惊的是，这个 USB 的磁盘容量只有 4MB。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/usb-drive-4mb-space-only.webp?resize=800%2C324&amp;ssl=1" alt=""></p><p>你试图格式化它，但它可能不会让你这么做。即使你设法格式化它，USB 的大小现在也从通常的 8GB、16GB 或 32GB 缩减到只有 4MB。</p><p>你失去了你的 USB 吗？并非如此。你的 USB 并没有完全被破坏。你仍然可以用一个小技巧来格式化它，并舒适地使用它。</p><p>让我告诉你如何在 Windows 和 Linux 中把可启动的 USB 恢复到可用的状态。</p><h3 id="格式化由-rufus-或-etcher-创建的-live-linux-usb-在-windows-下" tabindex="-1">格式化由 Rufus 或 Etcher 创建的 Live Linux USB （在 Windows 下） <a class="header-anchor" href="#格式化由-rufus-或-etcher-创建的-live-linux-usb-在-windows-下" aria-label="Permalink to “格式化由 Rufus 或 Etcher 创建的 Live Linux USB （在 Windows 下）”">​</a></h3><p>你在 Windows 中看到只有 4MB 的磁盘空间。你知道为什么吗？因为在创建 Live Linux USB 时，该工具在 FAT32 文件系统中创建了一个 4MB 的 EFI 分区。其他的分区是在 Linux 的 Ext4 文件系统中，而这是不被 Windows 识别的。</p><p>这就是为什么你的 Windows 系统只看到 4MB 的 EFI 分区，并显示 USB 大小为 4MB。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/mystery-behind-4-mb-linux-live-usb.webp?resize=800%2C400&amp;ssl=1" alt="Windows only see the EFI partition on the USB"></p><p>总而言之，你需要做的是删除 USB 盘上的所有分区，用删除现有分区后得到的空闲空间创建一个新的 NTFS 或 FAT32 分区。这就行了。</p><p>让我展示一下详细的步骤。</p><h4 id="步骤-1" tabindex="-1">步骤 1： <a class="header-anchor" href="#步骤-1" aria-label="Permalink to “步骤 1：”">​</a></h4><p>进入 Windows 菜单，寻找“磁盘管理”工具。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/start-disk-management-tool-windows.webp?resize=800%2C694&amp;ssl=1" alt="Start disk management tool"></p><p>启动这个工具，它将显示你电脑上存在的所有磁盘。当然，这包括插入的 USB。</p><p><strong>选择正确的磁盘是非常重要的</strong>。从 U 盘的大小或“可移动”的标签中辨别出它是哪一个。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/identify-usb-disk-in-windows.webp?resize=800%2C509&amp;ssl=1" alt=""></p><h4 id="步骤-2" tabindex="-1">步骤 2： <a class="header-anchor" href="#步骤-2" aria-label="Permalink to “步骤 2：”">​</a></h4><p>我们的想法是删除 U 盘上的任何现有分区。未分配的空间不能被删除，但这也没关系。</p><p>在该分区上点击右键，然后点击“<ruby>删除卷<rt>Delete Volume</rt></ruby>”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/delete-partitions-on-usb-disk.webp?resize=800%2C464&amp;ssl=1" alt="Delete partitions on the USB disk"></p><p>当要求你确认时，按“<ruby>是<rt>Yes</rt></ruby>”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/confirm-deletion-of-partition.webp?resize=800%2C357&amp;ssl=1" alt="Confirm deletion of partition"></p><p>你的目标是只有一个未分配的空间块。当你看到它时，右击它并点击“<ruby>新建简单卷……<rt>New Simple Volume...</rt></ruby>”来创建一个分区。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/Create-New-Partition.webp?resize=800%2C471&amp;ssl=1" alt="Create New Simple Volume partition"></p><p>接下来的步骤很简单。点击“<ruby>下一步<rt>Next &gt;</rt></ruby>”，选择整个可用空间，给它分配一个字母，选择文件系统（FAT32 或 NTFS），并将其格式化。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-1.png?resize=731%2C590&amp;ssl=1" alt="Click Next"></p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-2.png?resize=735%2C589&amp;ssl=1" alt="Use entire available space"></p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-3.png?resize=732%2C590&amp;ssl=1" alt="Give it a drive letter"></p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-4.png?resize=669%2C527&amp;ssl=1" alt="Use FAT 32 or NTFS, Name the USB if you want"></p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-5.png?resize=670%2C524&amp;ssl=1" alt="Revise all the changes"></p><p>完成后，你会看到 USB 已经恢复到正常状态，你可以开始向它复制粘贴数据。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/live-Linux-USB-formatted-successfully.webp?resize=800%2C571&amp;ssl=1" alt="USB is back to normal state"></p><p>你现在可以像以前一样使用你的 USB 了。</p><p>这些步骤是针对 Windows 的。如果你使用 Linux 呢？</p><h3 id="在-linux-上格式化-live-usb" tabindex="-1">在 Linux 上格式化 Live USB <a class="header-anchor" href="#在-linux-上格式化-live-usb" aria-label="Permalink to “在 Linux 上格式化 Live USB”">​</a></h3><p>我注意到，由 Etcher 和这类工具创建的 Live USB 经常拒绝被文件管理器中的右键格式化选项正确格式化。</p><p>除此之外，你可以像在 Windows 中那样做：删除现有的分区，用整个可用空间创建一个新的分区。</p><p>这里使用 GNOME “磁盘” 工具。它已经安装在 Ubuntu 和许多其他 Linux 发行版上。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/start-disk-app.webp?resize=791%2C256&amp;ssl=1" alt="Start disk app"></p><p><strong>同样，确保你在这里选择了外部 USB 盘。</strong></p><p>你会看到 U 盘上的各种分区。试着从上面的菜单中格式化该磁盘。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/format-usb-in-disks-tool.webp?resize=800%2C434&amp;ssl=1" alt="Format disk"></p><p><strong>如果这不起作用，逐个删除分区</strong>，然后把整个 USB 作为自由空间。</p><p>当你创建了整个自由空间后，点击 “+” 号，在上面创建一个 NTFS 或 FAT32 文件系统的分区。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/create-partition-on-usb.webp?resize=800%2C418&amp;ssl=1" alt=""></p><p>用 NTFS（或 FAT32）创建分区，给它起个合适的名字，然后你就可以像以前一样使用这个 USB 了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>像 Rufus 和 Etcher 这样的工具并没有真正破坏你的 USB。这就是它们的功能，通过在磁盘上创建一个不同的文件系统。但这样一来，Windows 操作系统就不能正确理解它。</p><p>好在只需付出一点努力就可以修复。我希望你也能够修复它。如果没有，请与我分享你的问题，我将尽力帮助你。</p><hr>',55)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/format-live-linux-usb/"},{default:p(()=>[...t[0]||(t[0]=[s("https://itsfoss.com/format-live-linux-usb/",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...t[2]||(t[2]=[s("Abhishek Prakash",-1)])]),_:1}),t[7]||(t[7]=s(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[s("lujun9972",-1)])]),_:1}),t[8]||(t[8]=s(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...t[4]||(t[4]=[s("geekpi",-1)])]),_:1}),t[9]||(t[9]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[s("LCTT",-1)])]),_:1}),t[13]||(t[13]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[s("Linux中国",-1)])]),_:1}),t[14]||(t[14]=s(" 荣誉推出",-1))])])}const g=n(m,[["render",d]]);export{x as __pageData,g as default};
